        public Input<string>? ProviderName { get; set; }

        /// <summary>
        /// The space (its id or slug). Changing it replaces the connector.
        /// </summary>
        [Input("spaceId")]
        public Input<string>? SpaceId { get; set; }

        [Input("token")]
        private Input<string>? _token;

        /// <summary>
        /// The access token, shown by the API once when minted. Sensitive.
        /// </summary>
        public Input<string>? Token
        {
            get => _token;
            set
            {
                var emptySecret = Output.CreateSecret(0);
                _token = Output.Tuple<Input<string>?, int>(value, emptySecret).Apply(t => t.Item1);
            }
        }

        /// <summary>
        /// The first characters of the token, to recognise it in the console.
        /// </summary>
        [Input("tokenPrefix")]
        public Input<string>? TokenPrefix { get; set; }

        /// <summary>
        /// Any string; change it to mint a new token (the old one stops working). Only meaningful with &lt;span pulumi-lang-nodejs="`mintToken`" pulumi-lang-dotnet="`MintToken`" pulumi-lang-go="`mintToken`" pulumi-lang-python="`mint_token`" pulumi-lang-yaml="`mintToken`" pulumi-lang-java="`mintToken`" pulumi-lang-hcl="`mint_token`"&gt;`mintToken`&lt;/span&gt;.
        /// </summary>
        [Input("tokenRotation")]
        public Input<string>? TokenRotation { get; set; }

        public ConnectorState()
        {
        }
        public static new ConnectorState Empty => new ConnectorState();
    }
}
